import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int md = sc.nextInt();

        int[][] c = new int[n + 1][n + 1];
        int[][] dpf = new int[n + 1][m + 1];
        int[][] dpr = new int[n + 1][m + 1];
        long[] f = new long[n + 1];
        long[] rst = new long[n + 1];

        // Precompute binomial coefficients modulo md
        for (int i = 0; i <= n; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % md;
            }
        }

        // Helper function for sum
        // Since Java doesn't support nested functions, define as static method
        // But for simplicity, define inline
        // sum(x) = x*(x+1)/2
        // We'll implement as a static method below

        // Initialize rst and f
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= i; k++) {
                long cur = c[i][k];
                long crst = 0;
                if (k > 0) {
                    crst = (crst * f[k - 1] + cur * rst[k - 1]) % md;
                    cur = (cur * f[k - 1]) % md;
                }
                if (k < i) {
                    crst = (crst * f[i - k - 1] + cur * rst[i - k - 1]) % md;
                    cur = (cur * f[i - k - 1]) % md;
                }
                rst[i] = (rst[i] + crst * (i + 2) + cur * (sum(k) + sum(i - k))) % md;
                f[i] = (f[i] + (i + 2) * cur) % md;
            }
        }

        // Initialize DP arrays
        dpf[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i && j <= m; j++) {
                dpf[i][j] = dpf[i - 1][j];
                dpr[i][j] = dpr[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    int prev = i - k;
                    if (prev > 0) prev--;
                    if (j - k <= prev) {
                        long temp1 = (dpr[prev][j - k] * f[k - 1] + dpf[prev][j - k] * rst[k - 1]) % md;
                        long temp2 = (dpf[prev][j - k] * f[k - 1]) % md;
                        dpr[i][j] = (int)((dpr[i][j] + c[j][k] * temp1) % md);
                        dpf[i][j] = (int)((dpf[i][j] + c[j][k] * temp2) % md);
                    }
                }
            }
        }

        System.out.println(dpr[n][m]);
        sc.close();
    }

    static long sum(long x) {
        return (x * (x + 1L)) / 2;
    }
}

